const {spawnSync} = require('child_process');
const BIN='/workspace/dataset/test4_executable';
function run(bufOrStr){
  const v = Buffer.isBuffer(bufOrStr)? bufOrStr.toString('utf8') : bufOrStr;
  const r = spawnSync(BIN, ['--a', v], {encoding:'buffer'});
  return {in: Buffer.from(v,'utf8').toString('hex'), out:(r.stdout||Buffer.alloc(0)).toString('hex'), err:(r.stderr||Buffer.alloc(0)).toString('utf8').trim(), code:r.status};
}
module.exports={run};
if(require.main===module){
  const args=process.argv.slice(2);
  for(const h of args){
    const b=Buffer.from(h,'hex');
    const r=run(b);
    console.log(`IN ${r.in}  OUT ${r.out}  CODE ${r.code}  ERR ${r.err}`);
  }
}
